(()=>{'use strict';const D=window.CATALOG,mode=document.body.dataset.mode,params=mode==='parameters',rows=params?D.parameters:D.functions,P=new Map(D.parameters.map(x=>[x.id,x])),F=new Map(D.functions.map(x=>[x.id,x])),V=new Map(D.valueClasses.map(x=>[x.id,x]));const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pLink=(id,label)=>'<a href="PARAMETRI.html#'+encodeURIComponent(id)+'">'+esc(label||P.get(id)?.name||id)+'</a>',fLink=(id,label)=>'<a href="FUNCTII.html#'+encodeURIComponent(id)+'">'+esc(label||F.get(id)?.name||id)+'</a>';
const srcLink=e=>'<a href="../reconstituit/jadx/app/src/main/java/'+e.file.split('/').map(encodeURIComponent).join('/')+'">'+esc(e.file)+'</a> · linia '+e.line;
const list=a=>a?.length?'<ul>'+a.map(x=>'<li>'+esc(typeof x==='object'?JSON.stringify(x):x)+'</li>').join('')+'</ul>':'<p class="muted">Neconfirmat / neextras pentru această intrare.</p>';
const val=x=>typeof x==='object'?'<pre>'+esc(JSON.stringify(x,null,2))+'</pre>':esc(x);
function dl(o){return '<dl>'+Object.entries(o).filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+val(v)+'</dd>').join('')+'</dl>'}
const sources=a=>'<h3>Dovezi și surse</h3>'+a.map(e=>'<div class="source">'+srcLink(e)+'<div class="muted">'+esc(e.role||'sursă')+'</div>'+(e.excerpt?'<details><summary>Expresie / corp observat</summary><pre>'+esc(e.excerpt)+'</pre></details>':'')+'</div>').join('');
function pTable(ids,f){if(!ids.length)return '<p class="muted">Nu există câmpuri atribuite automat acestei direcții. Verificați semnătura, delegările și sursa.</p>';return '<div class="scroll"><table><thead><tr><th>Parametru / cale</th><th>Tip și format</th><th>Valori / observație</th></tr></thead><tbody>'+ids.map(id=>{const p=P.get(id),paths=[...(f.schemaPaths||[]),...(f.localModelPaths||[])].filter(x=>x.parameterId===id).map(x=>(x.profile?x.profile+': ':'')+x.path+(x.representation?' ['+x.representation+']':''));return '<tr><td>'+pLink(id)+'<br><small>'+esc(paths.length?[...new Set(paths)].join(' · '):p.direction)+'</small></td><td><code>'+esc(p.javaType)+'</code><br>'+esc(p.format)+'</td><td>'+esc(p.constantValue!==undefined?'constantă: '+JSON.stringify(p.constantValue):p.values?JSON.stringify(p.values):p.rule||p.requirement)+'</td></tr>'}).join('')+'</tbody></table></div>'}
function renderP(p){return '<span class="label">'+esc(p.context)+'</span><h2>'+esc(p.name)+'</h2><span class="badge">'+esc(p.javaType)+'</span><span class="badge">'+esc(p.direction)+'</span><p>'+esc(p.description)+'</p>'+dl({'ID':p.id,'Domeniu separat':p.scope,'Profil':p.profile,'Cale pe fir verificată':p.wirePath,'Expresii de rezultat observate':p.observedExpressions,'Câmp Java':p.javaField,'Format':p.format,'Clasă de valori':V.get(p.valueClassId)?.name,'Unitate':p.unit,'Offset':p.offset,'Lățime':p.width,'Obligativitate':p.requirement,'Nulabilitate':p.nullableStatus?p.nullableStatus:p.nullable===null?'necunoscută':p.nullable===undefined?undefined:p.nullable?'@Nullable':'@NotNull','Regulă':p.rule,'Conversie':p.coercion,'Variante de conversie':p.coercionVariants,'Chei observate':p.observedKeys,'Statutul cheii':p.keyStatus,'Structura rezultatului':p.envelope,'Reverificare statică':p.staticReverification,'Expresie sursă':p.expression,'Constantă':p.constantValue,'Valori observate':p.observedValues,'Valori și sensuri':p.values,'Domeniu de stocare':p.storageRange,'Interval observat':p.observedRange,'Valoare implicită':p.defaultValue,'Statut implicit':p.defaultStatus,'Fallback parser':p.parserFallback,'Expresie Java fallback':p.parserFallbackExpression,'Dovadă DEX':p.dexEvidence,'Sursă oficială de tip':p.officialSource,'Limite':p.constraintStatus,'Nivel de dovadă':p.confidence})+'<p><a href="CLASE_VALORI.html#'+esc(p.valueClassId)+'">Definiția clasei de valori</a></p><h3>Funcții corelate ('+p.functionIds.length+')</h3>'+(p.functionIds.length?'<ul>'+p.functionIds.map(id=>'<li>'+fLink(id)+' <small>'+esc(F.get(id)?.kind)+'</small></li>').join('')+'</ul>':'<p class="muted">Câmp inventariat în clasă; consumatorul nu a fost atribuit automat. Inventarul complet păstrează toate metodele clasei.</p>')+(p.relatedParameterIds.length?'<h3>Transformări / argumente asociate</h3><ul>'+p.relatedParameterIds.map(id=>'<li>'+pLink(id,P.get(id)?.name+' · '+P.get(id)?.context)+'</li>').join('')+'</ul>':'')+(p.sameNameParameterIds.length?'<details><summary>Același nume în alte domenii ('+p.sameNameParameterIds.length+')</summary><p>Aceste intrări nu sunt presupuse echivalente.</p><ul>'+p.sameNameParameterIds.map(id=>'<li>'+pLink(id,P.get(id)?.context+' · '+P.get(id)?.javaType)+'</li>').join('')+'</ul></details>':'')+sources(p.evidence)+'<details><summary>Fișa completă JSON</summary><pre>'+esc(JSON.stringify(p,null,2))+'</pre></details>'}
function renderF(f){return '<span class="label">'+esc(f.kind)+'</span><h2>'+esc(f.name)+'</h2>'+(f.opt||[]).map(x=>'<span class="badge">opt '+esc(typeof x==='object'?x.expression:x)+'</span>').join('')+'<p>'+esc(f.description)+'</p><pre>'+esc(f.signature)+'</pre>'+dl({'ID':f.id,'Clasă':f.owner,'Transport':f.transport,'Răspuns / retur':f.returns,'Retur în cod':f.returnExpressions,'Efecte':f.sideEffects,'Nivel de dovadă':f.confidence,'Traseu prin listener':f.listenerTrace,'Transmiterea rezultatului':f.resultForwarding})+(f.channels?.length?'<h3>Canale Flutter</h3>'+list(f.channels.map(x=>x.expression)):'')+'<h3>Intrări și configurare ('+f.inputParameterIds.length+')</h3>'+pTable(f.inputParameterIds,f)+'<h3>Ieșiri / câmpuri răspuns ('+f.outputParameterIds.length+')</h3>'+pTable(f.outputParameterIds,f)+(f.localModelParameterIds?.length?'<h3>Modele Java locale corelate ('+f.localModelParameterIds.length+')</h3><p>Câmpuri ale modelelor menționate sau construite de aplicație. Apariția aici nu dovedește o cheie primită de pe fir.</p>'+pTable(f.localModelParameterIds,f):'')+(f.resultCoverage?'<h3>Rezultate și evenimente Flutter</h3><p>'+esc(f.resultCoverage)+'</p>'+dl({'ACK verificat':f.resultContract,'Canal de evenimente':f.eventChannel,'Variante callback verificate':f.eventContracts,'Producători observați':f.resultObservations,'Hărți de evenimente observate':f.eventProducerObservations,'Erori Result/EventSink':f.resultErrorContracts}):'')+'<h3>Precondiții</h3>'+list(f.preconditions)+'<h3>Erori și validări observate</h3>'+list(f.errors)+'<h3>Comportament, temporizări și particularități</h3>'+list(f.notes)+(f.mergedMaps?.length?'<h3>Hărți adăugate</h3>'+list(f.mergedMaps):'')+(f.relatedFunctionIds.length?'<h3>Funcții / straturi corelate</h3><ul>'+f.relatedFunctionIds.map(id=>'<li>'+fLink(id)+'</li>').join('')+'</ul>':'')+'<h3>Aspecte neconfirmate</h3>'+list(f.unknowns)+sources(f.evidence)+'<details><summary>Fișa completă JSON, delegări și căi de câmp</summary><pre>'+esc(JSON.stringify(f,null,2))+'</pre></details>'}
let filtered=rows,page=0,selected='',size=35;const search=rows.map(r=>({r,s:[r.name,r.context,r.scope,r.owner,r.javaType,r.javaField,r.signature,r.description,r.transport,...(r.opt||[]),...(r.aliases||[])].join(' ').toLowerCase()}));
const filters=[...new Set(rows.map(r=>params?r.valueClassId:r.kind))].sort();$('#filter').innerHTML='<option value="">Toate '+(params?'clasele de valori':'tipurile de funcții')+'</option>'+filters.map(v=>'<option value="'+esc(v)+'">'+esc(params?V.get(v)?.name:v)+'</option>').join('');
function draw(){const start=page*size;$('#count').textContent=filtered.length.toLocaleString('ro-RO')+' rezultate din '+rows.length.toLocaleString('ro-RO');$('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/size));$('#prev').disabled=page===0;$('#next').disabled=start+size>=filtered.length;$('#results').innerHTML=filtered.slice(start,start+size).map(r=>'<button class="result" data-id="'+r.id+'" aria-current="'+(r.id===selected)+'"><strong>'+esc(r.name)+'</strong><small>'+esc(params?r.context:r.kind+' · '+(r.opt||[]).join(', '))+'</small><small>'+esc(params?r.javaType:r.signature)+'</small></button>').join('')||'<p>Nu există rezultate pentru filtrul ales.</p>';$('#results').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.id}));}
function select(){const key=decodeURIComponent(location.hash.slice(1));const r=(params?P:F).get(key);if(r){selected=r.id;$('#detail').innerHTML=params?renderP(r):renderF(r);draw();}else if(key){$('#detail').innerHTML='<h2>Intrare negăsită</h2><p>ID-ul nu aparține acestui dicționar.</p>';}}
function filter(){const terms=$('#search').value.toLowerCase().trim().split(/\s+/).filter(Boolean),v=$('#filter').value;filtered=search.filter(x=>terms.every(t=>x.s.includes(t))&&(!v||(params?x.r.valueClassId:x.r.kind)===v)).map(x=>x.r);page=0;draw();}
$('#search').addEventListener('input',filter);$('#filter').addEventListener('change',filter);$('#prev').onclick=()=>{page--;draw()};$('#next').onclick=()=>{page++;draw()};window.addEventListener('hashchange',select);draw();select();window.CATALOG_UI_READY=true;
})();
